/* ============================================================
   GlobalStone — Corporate Website Styles
   ============================================================ */

:root {
  --primary: #0A1628;
  --primary-dark: #060E1A;
  --secondary: #012A2D;
  --accent: #C9A84C;
  --accent-hover: #B8953F;
  --teal: #0E7C7B;
  --teal-light: #12A5A4;
  --gray-100: #F7F8FA;
  --gray-200: #E8EBF0;
  --gray-300: #D1D5DE;
  --gray-400: #9BA3B5;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --white: #FFFFFF;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --max-width: 1280px;
  --header-height: 80px;
  --transition: 0.3s ease;
  --shadow-sm: 0 1px 3px rgba(10,22,40,0.08);
  --shadow-md: 0 4px 16px rgba(10,22,40,0.10);
  --shadow-lg: 0 8px 32px rgba(10,22,40,0.14);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-sans);
  color: var(--gray-700);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { text-decoration: none; color: inherit; transition: color var(--transition); }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ─── Typography ─── */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-serif); color: var(--primary); line-height: 1.2; font-weight: 700; }
h1 { font-size: clamp(2.2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.2rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

.section-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 12px;
}

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: 4px;
  transition: all var(--transition);
  letter-spacing: 0.01em;
}

.btn-primary {
  background: var(--accent);
  color: var(--primary);
}
.btn-primary:hover { background: var(--accent-hover); transform: translateY(-1px); box-shadow: var(--shadow-md); }

.btn-outline {
  border: 2px solid var(--white);
  color: var(--white);
  background: transparent;
}
.btn-outline:hover { background: var(--white); color: var(--primary); }

.btn-outline-dark {
  border: 2px solid var(--primary);
  color: var(--primary);
  background: transparent;
}
.btn-outline-dark:hover { background: var(--primary); color: var(--white); }

.btn-text {
  padding: 0;
  color: var(--teal);
  font-weight: 600;
  font-size: 0.9375rem;
}
.btn-text:hover { color: var(--teal-light); }
.btn-text .arrow { transition: transform var(--transition); }
.btn-text:hover .arrow { transform: translateX(4px); }

/* ─── Header / Navigation ─── */
.site-header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: var(--primary);
  height: var(--header-height);
  transition: background var(--transition), box-shadow var(--transition);
}

.site-header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.2); }

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.logo {
  font-family: var(--font-sans);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 10px;
}
.logo-icon {
  width: 36px; height: 36px;
  background: var(--accent);
  border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem; font-weight: 900; color: var(--primary);
}

.main-nav { display: flex; align-items: center; gap: 0; height: 100%; }
.main-nav > li { height: 100%; position: relative; }
.main-nav > li > a {
  display: flex; align-items: center; height: 100%;
  padding: 0 20px;
  color: rgba(255,255,255,0.85);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color var(--transition);
}
.main-nav > li > a:hover,
.main-nav > li > a.active { color: var(--white); }

.nav-item-services > a::after {
  content: '';
  width: 6px; height: 6px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
  margin-left: 6px;
  transition: transform var(--transition);
}
.nav-item-services.open > a::after { transform: rotate(-135deg); }

/* ─── Mega Menu ─── */
.mega-menu {
  position: absolute;
  top: 100%; left: 50%;
  transform: translateX(-50%);
  min-width: 640px;
  background: var(--white);
  border-radius: 0 0 8px 8px;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s ease, visibility 0.25s ease, transform 0.25s ease;
  transform: translateX(-50%) translateY(-8px);
  padding: 32px 36px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}

.nav-item-services.open .mega-menu,
.nav-item-services:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.mega-column h4 {
  font-family: var(--font-sans);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gray-400);
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--gray-200);
}

.mega-column ul li a {
  display: block;
  padding: 8px 0;
  font-size: 0.9375rem;
  color: var(--gray-700);
  font-weight: 500;
  transition: color var(--transition), padding-left var(--transition);
}
.mega-column ul li a:hover { color: var(--teal); padding-left: 6px; }

/* ─── Mobile Navigation ─── */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  padding: 4px 0;
  z-index: 1010;
}
.hamburger span {
  width: 100%; height: 2px;
  background: var(--white);
  border-radius: 2px;
  transition: all var(--transition);
}
.hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0; right: 0; bottom: 0;
  background: var(--primary);
  overflow-y: auto;
  padding: 24px;
  z-index: 999;
}
.mobile-nav.active { display: block; }

.mobile-nav > ul > li { border-bottom: 1px solid rgba(255,255,255,0.1); }
.mobile-nav > ul > li > a,
.mobile-nav > ul > li > button {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; padding: 16px 0;
  color: var(--white); font-size: 1.0625rem; font-weight: 500;
  text-align: left;
}
.mobile-nav .accordion-trigger .chevron {
  transition: transform var(--transition);
  font-size: 0.75rem;
}
.mobile-nav .accordion-trigger.open .chevron { transform: rotate(180deg); }

.mobile-nav .accordion-panel {
  display: none;
  padding: 0 0 16px 16px;
}
.mobile-nav .accordion-panel.open { display: block; }
.mobile-nav .accordion-panel a {
  display: block; padding: 10px 0;
  color: rgba(255,255,255,0.75); font-size: 0.9375rem;
}
.mobile-nav .accordion-panel a:hover { color: var(--white); }
.mobile-nav .accordion-panel h5 {
  font-family: var(--font-sans);
  font-size: 0.7rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.12em;
  color: var(--accent); margin: 8px 0;
}

/* ─── Hero Section ─── */
.hero {
  position: relative;
  min-height: 560px;
  display: flex; align-items: center;
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  padding-top: var(--header-height);
  overflow: hidden;
}
.hero-bg {
  position: absolute; inset: 0;
  background-size: cover; background-position: center;
  opacity: 0.25;
}
.hero-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, rgba(10,22,40,0.85) 0%, rgba(1,42,45,0.7) 100%);
}
.hero-content { position: relative; z-index: 1; padding: 80px 0; max-width: 680px; }
.hero-content h1 { color: var(--white); margin-bottom: 20px; }
.hero-content p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  line-height: 1.7;
  margin-bottom: 32px;
  max-width: 560px;
}

/* ─── Featured Insights ─── */
.featured-insights { padding: 80px 0; background: var(--white); }
.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 40px;
}
.insight-card {
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
  background: var(--white);
}
.insight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.insight-card-image {
  height: 200px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  position: relative;
  overflow: hidden;
}
.insight-card-image::after {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(10,22,40,0.3) 100%);
}
.insight-card-image .placeholder-icon {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 3rem;
  opacity: 0.3;
  color: var(--white);
}
.insight-card-body { padding: 24px; }
.insight-tag {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--teal);
  margin-bottom: 8px;
}
.insight-card-body h3 { font-size: 1.125rem; margin-bottom: 12px; line-height: 1.4; }
.insight-card-body p { font-size: 0.875rem; color: var(--gray-500); margin-bottom: 16px; }
.insight-date { font-size: 0.8125rem; color: var(--gray-400); }

/* ─── Announcement Banner ─── */
.announcement-banner {
  background: var(--secondary);
  padding: 24px 0;
}
.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.announcement-inner p {
  color: var(--white);
  font-size: 1.0625rem;
  font-weight: 600;
}

/* ─── About Statement ─── */
.about-statement { padding: 100px 0; background: var(--gray-100); }
.about-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.about-inner h2 { margin-bottom: 24px; }
.about-inner p { font-size: 1.0625rem; line-height: 1.8; color: var(--gray-600); margin-bottom: 32px; }
.about-image {
  height: 400px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 50%, var(--teal) 100%);
  border-radius: 8px;
  position: relative;
  overflow: hidden;
}
.about-image::after {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='100' height='100' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0 50 L50 0 L100 50 L50 100Z' fill='none' stroke='rgba(255,255,255,0.05)' stroke-width='1'/%3E%3C/svg%3E");
}

/* ─── What We Do (Vertical Tabs) ─── */
.what-we-do { padding: 100px 0; background: var(--white); }
.tabs-container {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 48px;
  margin-top: 48px;
  min-height: 320px;
}
.tab-list { display: flex; flex-direction: column; gap: 0; }
.tab-btn {
  text-align: left;
  padding: 20px 24px;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--gray-500);
  border-left: 3px solid var(--gray-200);
  transition: all var(--transition);
  background: transparent;
}
.tab-btn:hover { color: var(--primary); background: var(--gray-100); }
.tab-btn.active {
  color: var(--primary);
  border-left-color: var(--accent);
  background: var(--gray-100);
}

.tab-panel {
  display: none;
  padding: 32px 40px;
  background: var(--gray-100);
  border-radius: 8px;
  animation: fadeIn 0.4s ease;
}
.tab-panel.active { display: block; }
.tab-panel h3 { margin-bottom: 16px; font-size: 1.5rem; }
.tab-panel p { font-size: 1.0625rem; color: var(--gray-600); line-height: 1.8; margin-bottom: 24px; }
.tab-panel ul { margin-bottom: 24px; }
.tab-panel ul li {
  padding: 8px 0;
  padding-left: 20px;
  position: relative;
  color: var(--gray-600);
}
.tab-panel ul li::before {
  content: '';
  position: absolute; left: 0; top: 16px;
  width: 8px; height: 8px;
  background: var(--accent);
  border-radius: 50%;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ─── Newsletter ─── */
.newsletter {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  text-align: center;
}
.newsletter h2 { color: var(--white); margin-bottom: 12px; }
.newsletter p { color: rgba(255,255,255,0.8); font-size: 1.0625rem; margin-bottom: 32px; }
.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid rgba(255,255,255,0.2);
  border-radius: 4px;
  background: rgba(255,255,255,0.1);
  color: var(--white);
  font-size: 0.9375rem;
  font-family: var(--font-sans);
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.5); }
.newsletter-form input:focus { outline: none; border-color: var(--accent); }

/* ─── Latest Insights ─── */
.latest-insights { padding: 80px 0; background: var(--gray-100); }
.latest-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 40px;
}

/* ─── Commitment Pillars ─── */
.commitment { padding: 100px 0; background: var(--white); }
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-top: 48px;
}
.commitment-card {
  padding: 32px 28px;
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  transition: all var(--transition);
}
.commitment-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}
.commitment-card .card-icon {
  width: 48px; height: 48px;
  background: rgba(201,168,76,0.1);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
  font-size: 1.25rem;
  color: var(--accent);
}
.commitment-card h3 { font-size: 1.125rem; margin-bottom: 12px; }
.commitment-card p { font-size: 0.9rem; color: var(--gray-500); line-height: 1.6; margin-bottom: 20px; }

/* ─── Footer ─── */
.site-footer { background: var(--primary-dark); color: rgba(255,255,255,0.7); padding: 64px 0 0; }
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-brand .logo { margin-bottom: 16px; }
.footer-brand p { font-size: 0.875rem; line-height: 1.7; max-width: 300px; color: rgba(255,255,255,0.5); }
.footer-col h4 {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--white);
  margin-bottom: 20px;
}
.footer-col ul li a {
  display: block;
  padding: 6px 0;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.5);
  transition: color var(--transition);
}
.footer-col ul li a:hover { color: var(--accent); }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-size: 0.8125rem;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-legal { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-legal a { color: rgba(255,255,255,0.4); }
.footer-legal a:hover { color: var(--accent); }

/* ─── Services Page ─── */
.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}
.service-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 40px 32px;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}
.service-card:hover { border-color: var(--teal); box-shadow: var(--shadow-md); transform: translateY(-4px); }
.service-card .card-icon {
  width: 56px; height: 56px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 24px;
  font-size: 1.5rem;
  color: var(--accent);
}
.service-card h3 { margin-bottom: 12px; }
.service-card p { font-size: 0.9375rem; color: var(--gray-500); line-height: 1.7; margin-bottom: 24px; flex: 1; }

/* ─── Intro Statement ─── */
.intro-statement { padding: 80px 0; background: var(--white); text-align: center; }
.intro-statement p { max-width: 720px; margin: 0 auto; font-size: 1.125rem; color: var(--gray-600); line-height: 1.8; }

/* ─── Capabilities Grid ─── */
.capabilities-section { padding: 80px 0; background: var(--gray-100); }
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  margin-top: 48px;
}
.capability-card {
  background: var(--white);
  border-radius: 8px;
  padding: 36px 28px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  border-left: 4px solid transparent;
}
.capability-card:hover { box-shadow: var(--shadow-md); border-left-color: var(--accent); transform: translateY(-2px); }
.capability-card h3 { font-size: 1.125rem; margin-bottom: 12px; }
.capability-card p { font-size: 0.9rem; color: var(--gray-500); line-height: 1.7; }

/* ─── Featured Topics ─── */
.featured-topics { padding: 80px 0; background: var(--white); }
.topics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.topic-card {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  border-radius: 8px;
  padding: 40px 28px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.topic-card::before {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 0%, rgba(201,168,76,0.15) 100%);
  opacity: 0;
  transition: opacity var(--transition);
}
.topic-card:hover::before { opacity: 1; }
.topic-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.topic-card h3 { color: var(--white); font-size: 1.125rem; }

/* ─── Deal Flow CTA ─── */
.deal-flow-cta {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--secondary) 0%, var(--primary) 100%);
  text-align: center;
}
.deal-flow-cta h2 { color: var(--white); margin-bottom: 16px; }
.deal-flow-cta p { color: rgba(255,255,255,0.8); font-size: 1.0625rem; margin-bottom: 32px; max-width: 600px; margin-left: auto; margin-right: auto; }

/* ─── Testimonial ─── */
.testimonial-section { padding: 80px 0; background: var(--white); }
.testimonial-card {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
  padding: 48px;
}
.testimonial-card blockquote {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  color: var(--primary);
  line-height: 1.6;
  font-style: italic;
  margin-bottom: 24px;
  position: relative;
}
.testimonial-card blockquote::before {
  content: '\201C';
  font-size: 4rem;
  color: var(--accent);
  line-height: 1;
  display: block;
  margin-bottom: 8px;
}
.testimonial-card cite {
  font-style: normal;
  font-size: 0.9375rem;
  color: var(--gray-500);
}
.testimonial-card cite strong { color: var(--primary); display: block; margin-bottom: 4px; }

/* ─── Property Types CTA ─── */
.property-types { padding: 80px 0; background: var(--gray-100); }
.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
  margin-top: 40px;
}
.property-type-card {
  background: var(--white);
  border-radius: 8px;
  padding: 32px 20px;
