}

/* ─── Commitment Pillars ─── */
.commitment { padding: 100px 0; background: var(--white); }
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-top: 48px;
}
.commitment-card {
  padding: 32px 28px;
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  transition: all var(--transition);
}
.commitment-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}
.commitment-card .card-icon {
  width: 48px; height: 48px;
  background: rgba(201,168,76,0.1);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
  font-size: 1.25rem;
  color: var(--accent);
}
.commitment-card h3 { font-size: 1.125rem; margin-bottom: 12px; }
.commitment-card p { font-size: 0.9rem; color: var(--gray-500); line-height: 1.6; margin-bottom: 20px; }

/* ─── Footer ─── */
.site-footer { background: var(--primary-dark); color: rgba(255,255,255,0.7); padding: 64px 0 0; }
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-brand .logo { margin-bottom: 16px; }
.footer-brand p { font-size: 0.875rem; line-height: 1.7; max-width: 300px; color: rgba(255,255,255,0.5); }
.footer-col h4 {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--white);
  margin-bottom: 20px;
}
.footer-col ul li a {
  display: block;
  padding: 6px 0;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.5);
  transition: color var(--transition);
}
.footer-col ul li a:hover { color: var(--accent); }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-size: 0.8125rem;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-legal { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-legal a { color: rgba(255,255,255,0.4); }
.footer-legal a:hover { color: var(--accent); }

/* ─── Services Page ─── */
.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}
.service-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 40px 32px;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}
.service-card:hover { border-color: var(--teal); box-shadow: var(--shadow-md); transform: translateY(-4px); }
.service-card .card-icon {
  width: 56px; height: 56px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 24px;
  font-size: 1.5rem;
  color: var(--accent);
}
.service-card h3 { margin-bottom: 12px; }
.service-card p { font-size: 0.9375rem; color: var(--gray-500); line-height: 1.7; margin-bottom: 24px; flex: 1; }

/* ─── Intro Statement ─── */
.intro-statement { padding: 80px 0; background: var(--white); text-align: center; }
.intro-statement p { max-width: 720px; margin: 0 auto; font-size: 1.125rem; color: var(--gray-600); line-height: 1.8; }

/* ─── Capabilities Grid ─── */
.capabilities-section { padding: 80px 0; background: var(--gray-100); }
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  margin-top: 48px;
}
.capability-card {
  background: var(--white);
  border-radius: 8px;
  padding: 36px 28px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  border-left: 4px solid transparent;
}
.capability-card:hover { box-shadow: var(--shadow-md); border-left-color: var(--accent); transform: translateY(-2px); }
.capability-card h3 { font-size: 1.125rem; margin-bottom: 12px; }
.capability-card p { font-size: 0.9rem; color: var(--gray-500); line-height: 1.7; }

/* ─── Featured Topics ─── */
.featured-topics { padding: 80px 0; background: var(--white); }
.topics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.topic-card {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  border-radius: 8px;
  padding: 40px 28px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.topic-card::before {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 0%, rgba(201,168,76,0.15) 100%);
  opacity: 0;
  transition: opacity var(--transition);
}
.topic-card:hover::before { opacity: 1; }
.topic-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.topic-card h3 { color: var(--white); font-size: 1.125rem; }

/* ─── Deal Flow CTA ─── */
.deal-flow-cta {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--secondary) 0%, var(--primary) 100%);
  text-align: center;
}
.deal-flow-cta h2 { color: var(--white); margin-bottom: 16px; }
.deal-flow-cta p { color: rgba(255,255,255,0.8); font-size: 1.0625rem; margin-bottom: 32px; max-width: 600px; margin-left: auto; margin-right: auto; }

/* ─── Testimonial ─── */
.testimonial-section { padding: 80px 0; background: var(--white); }
.testimonial-card {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
  padding: 48px;
}
.testimonial-card blockquote {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  color: var(--primary);
  line-height: 1.6;
  font-style: italic;
  margin-bottom: 24px;
  position: relative;
}
.testimonial-card blockquote::before {
  content: '\201C';
  font-size: 4rem;
  color: var(--accent);
  line-height: 1;
  display: block;
  margin-bottom: 8px;
}
.testimonial-card cite {
  font-style: normal;
  font-size: 0.9375rem;
  color: var(--gray-500);
}
.testimonial-card cite strong { color: var(--primary); display: block; margin-bottom: 4px; }

/* ─── Property Types CTA ─── */
.property-types { padding: 80px 0; background: var(--gray-100); }
.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
  margin-top: 40px;
}
.property-type-card {
  background: var(--white);
  border-radius: 8px;
  padding: 32px 20px;
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
}
.property-type-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); border-color: var(--teal); }
.property-type-card .pt-icon {
  width: 48px; height: 48px;
  background: rgba(14,124,123,0.1);
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 16px;
  font-size: 1.25rem;
  color: var(--teal);
}
.property-type-card h4 { font-family: var(--font-sans); font-size: 0.9375rem; font-weight: 600; }

/* ─── Related Services ─── */
.related-services { padding: 80px 0; background: var(--white); }
.related-services-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 28px;
  margin-top: 40px;
}
.related-service-card {
  display: flex; align-items: center; gap: 24px;
  padding: 28px;
  background: var(--gray-100);
  border-radius: 8px;
  transition: all var(--transition);
}
.related-service-card:hover { background: var(--gray-200); transform: translateX(4px); }
.related-service-card .rs-icon {
  width: 56px; height: 56px;
  background: var(--primary);
  border-radius: 10px;
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  color: var(--accent);
  font-size: 1.25rem;
}
.related-service-card h4 { font-family: var(--font-sans); font-size: 1rem; font-weight: 600; margin-bottom: 4px; }
.related-service-card p { font-size: 0.8125rem; color: var(--gray-500); }

/* ─── Related Insights ─── */
.related-insights { padding: 80px 0; background: var(--gray-100); }

/* ─── Partners Carousel ─── */
.featured-partners { padding: 80px 0; background: var(--white); }
.carousel-wrapper { position: relative; overflow: hidden; margin-top: 40px; }
.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}
.carousel-slide {
  min-width: 100%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  padding: 0 4px;
}
.partner-card {
  background: var(--gray-100);
  border-radius: 8px;
  padding: 32px;
  text-align: center;
}
.partner-card .partner-logo {
  width: 80px; height: 80px;
  background: var(--gray-200);
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; color: var(--gray-400);
}
.partner-card h4 { font-family: var(--font-sans); font-size: 0.9375rem; margin-bottom: 8px; }
.partner-card p { font-size: 0.8125rem; color: var(--gray-500); }

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 24px;
}
.carousel-btn {
  width: 40px; height: 40px;
  border: 2px solid var(--gray-300);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1rem;
  color: var(--gray-600);
  transition: all var(--transition);
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); }

/* ─── Partnership Highlight ─── */
.partnership-highlight { padding: 100px 0; background: var(--white); }
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.partnership-inner h2 { margin-bottom: 24px; }
.partnership-inner p { font-size: 1.0625rem; color: var(--gray-600); line-height: 1.8; margin-bottom: 16px; }
.partnership-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 32px;
}
.stat-card {
  background: var(--gray-100);
  border-radius: 8px;
  padding: 32px 24px;
  text-align: center;
}
.stat-card .stat-number {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--accent);
  line-height: 1;
  margin-bottom: 8px;
}
.stat-card .stat-label {
  font-size: 0.875rem;
  color: var(--gray-500);
}
.partnership-image {
  height: 400px;
  background: linear-gradient(135deg, var(--secondary) 0%, var(--primary) 100%);
  border-radius: 8px;
  position: relative;
  overflow: hidden;
}

/* ─── What We Do (Service Detail variant) ─── */
.what-we-do-detail { padding: 80px 0; background: var(--white); }

/* ─── Hero Variants ─── */
.hero-services { min-height: 420px; }
.hero-subpage { min-height: 380px; }
.hero-subpage .hero-content { padding: 60px 0; }

/* ─── Page-specific breadcrumb ─── */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
  font-size: 0.8125rem;
}
.breadcrumb a { color: rgba(255,255,255,0.6); }
.breadcrumb a:hover { color: var(--white); }
.breadcrumb span { color: rgba(255,255,255,0.4); }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .insights-grid,
  .latest-insights-grid,
  .services-grid,
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .topics-grid { grid-template-columns: repeat(2, 1fr); }
  .property-types-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .about-inner,
  .partnership-inner { grid-template-columns: 1fr; }
  .tabs-container { grid-template-columns: 1fr; }
  .tab-list { flex-direction: row; overflow-x: auto; }
  .tab-btn { border-left: none; border-bottom: 3px solid var(--gray-200); white-space: nowrap; padding: 16px 20px; }
  .tab-btn.active { border-bottom-color: var(--accent); border-left: none; }
}

@media (max-width: 768px) {
  :root { --header-height: 64px; }
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .hero { min-height: 440px; }
  .hero-content { padding: 48px 0; }
  h1 { font-size: 2rem; }
  .insights-grid,
  .latest-insights-grid,
  .services-grid,
  .capabilities-grid,
  .commitment-grid,
  .topics-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
  .carousel-slide { grid-template-columns: 1fr; }
  .related-services-grid { grid-template-columns: 1fr; }
  .partnership-stats { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
  .announcement-inner { flex-direction: column; text-align: center; }
  .about-image,
  .partnership-image { height: 260px; }
}
