.testimonial-section { padding: 80px 0; background: var(--white); }
.testimonial-card {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
  padding: 48px;
}
.testimonial-card blockquote {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  color: var(--primary);
  line-height: 1.6;
  font-style: italic;
  margin-bottom: 24px;
  position: relative;
}
.testimonial-card blockquote::before {
  content: '\201C';
  font-size: 4rem;
  color: var(--accent);
  line-height: 1;
  display: block;
  margin-bottom: 8px;
}
.testimonial-card cite {
  font-style: normal;
  font-size: 0.9375rem;
  color: var(--gray-500);
}
.testimonial-card cite strong { color: var(--primary); display: block; margin-bottom: 4px; }

