.property-types { padding: 80px 0; background: var(--gray-100); }
.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
  margin-top: 40px;
}
.property-type-card {
  background: var(--white);
  border-radius: 8px;
  padding: 32px 20px;
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
}
.property-type-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); border-color: var(--teal); }
.property-type-card .pt-icon {
  width: 48px; height: 48px;
  background: rgba(14,124,123,0.1);
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 16px;
  font-size: 1.25rem;
  color: var(--teal);
}
.property-type-card h4 { font-family: var(--font-sans); font-size: 0.9375rem; font-weight: 600; }

/* ─── Related Services ─── */
.related-services { padding: 80px 0; background: var(--white); }
.related-services-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 28px;
  margin-top: 40px;
}
.related-service-card {
  display: flex; align-items: center; gap: 24px;
  padding: 28px;
  background: var(--gray-100);
  border-radius: 8px;
  transition: all var(--transition);
}
.related-service-card:hover { background: var(--gray-200); transform: translateX(4px); }
.related-service-card .rs-icon {
  width: 56px; height: 56px;
  background: var(--primary);
  border-radius: 10px;
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  color: var(--accent);
  font-size: 1.25rem;
}
.related-service-card h4 { font-family: var(--font-sans); font-size: 1rem; font-weight: 600; margin-bottom: 4px; }
.related-service-card p { font-size: 0.8125rem; color: var(--gray-500); }

/* ─── Related Insights ─── */
.related-insights { padding: 80px 0; background: var(--gray-100); }

/* ─── Partners Carousel ─── */
.featured-partners { padding: 80px 0; background: var(--white); }
.carousel-wrapper { position: relative; overflow: hidden; margin-top: 40px; }
.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}
.carousel-slide {
  min-width: 100%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  padding: 0 4px;
}
.partner-card {
  background: var(--gray-100);
  border-radius: 8px;
  padding: 32px;
  text-align: center;
}
.partner-card .partner-logo {
  width: 80px; height: 80px;
  background: var(--gray-200);
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; color: var(--gray-400);
}
.partner-card h4 { font-family: var(--font-sans); font-size: 0.9375rem; margin-bottom: 8px; }
.partner-card p { font-size: 0.8125rem; color: var(--gray-500); }

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 24px;
}
.carousel-btn {
  width: 40px; height: 40px;
  border: 2px solid var(--gray-300);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1rem;
  color: var(--gray-600);
  transition: all var(--transition);
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); }

/* ─── Partnership Highlight ─── */
.partnership-highlight { padding: 100px 0; background: var(--white); }
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.partnership-inner h2 { margin-bottom: 24px; }
.partnership-inner p { font-size: 1.0625rem; color: var(--gray-600); line-height: 1.8; margin-bottom: 16px; }
.partnership-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 32px;
}
.stat-card {
  background: var(--gray-100);
  border-radius: 8px;
  padding: 32px 24px;
  text-align: center;
}
.stat-card .stat-number {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--accent);
  line-height: 1;
  margin-bottom: 8px;
}
.stat-card .stat-label {
  font-size: 0.875rem;
  color: var(--gray-500);
}
.partnership-image {
  height: 400px;
  background: linear-gradient(135deg, var(--secondary) 0%, var(--primary) 100%);
  border-radius: 8px;
  position: relative;
  overflow: hidden;
}

/* ─── What We Do (Service Detail variant) ─── */
.what-we-do-detail { padding: 80px 0; background: var(--white); }

/* ─── Hero Variants ─── */
.hero-services { min-height: 420px; }
.hero-subpage { min-height: 380px; }
.hero-subpage .hero-content { padding: 60px 0; }

/* ─── Page-specific breadcrumb ─── */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
  font-size: 0.8125rem;
}
.breadcrumb a { color: rgba(255,255,255,0.6); }
.breadcrumb a:hover { color: var(--white); }
.breadcrumb span { color: rgba(255,255,255,0.4); }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
